<template>
  <view class="login-page">
    <!--
      本页按 MasterGo 设计稿「1A 登录入口」1:1 还原（设计画布 1125×2436px，
      对应 uni-app 750rpx 基准，换算比例 rpx = designPx × 2/3）。
      设计稿中的状态栏（9:41 时间/信号/电量）与灵动岛图案属于 MasterGo 导出模板自带的
      设备外壳装饰，并非页面真实内容——小程序运行时状态栏由系统原生绘制，此处按行业
      惯例不予还原，避免和真机状态栏重叠/冲突。
      本页使用默认导航栏（不能用 navigationStyle: custom）：微信的「返回首页」小房子
      只画在原生导航栏上，custom 会把整条栏去掉、只留右上角胶囊。从首页 reLaunch
      进来后，本页是页面栈最底层且不是首页，系统会自动显示小房子。内容区坐标已减去
      约 176rpx（状态栏 + 导航栏），避免和原生栏重叠后整体下移。
    -->
    <view class="login-page__logo-wrap">
      <view class="login-page__logo-bg"></view>
      <view class="login-page__logo-icon"></view>
    </view>

    <view class="login-page__title-wrap">
      <view class="login-page__title-cn"></view>
      <view class="login-page__title-en"></view>
    </view>

    <text class="login-page__subtitle">住进别人的生活 交换一段旅程</text>

    <!--
      微信一键登录必须使用 open-type="getPhoneNumber" 的原生按钮触发微信授权弹窗，
      不能用普通按钮 + JS 主动调起、也不能用 disabled 拦截点击（微信规定 disabled 按钮
      完全不响应任何事件，无法借此弹提示，见 design.md Uniapp 小节 Decisions 第 6 条）。
      未勾选协议时，在按钮上方盖一层可点击遮罩拦截点击并提示；勾选后遮罩移除，
      点击才能真正落到按钮上触发微信授权。
    -->
    <view class="login-page__btn-wrap login-page__btn-wrap--wechat">
      <button
        class="login-page__btn login-page__btn--wechat"
        open-type="getPhoneNumber"
        @getphonenumber="onGetPhoneNumber"
      >
        微信一键登录
      </button>
      <view v-if="!agreedToTerms" class="login-page__btn-mask" @tap="onWechatButtonTap"></view>
    </view>

    <view class="login-page__btn-wrap login-page__btn-wrap--outline">
      <button class="login-page__btn login-page__btn--outline" @tap="onOtherPhoneLogin">
        其他号码登录
      </button>
    </view>

    <view class="login-page__agreement">
      <view
        class="login-page__checkbox"
        :class="{ 'login-page__checkbox--checked': agreedToTerms }"
        @tap="toggleAgreement"
      >
        <text v-if="agreedToTerms" class="login-page__checkbox-mark">✓</text>
      </view>
      <text class="login-page__agreement-text">
        我已阅读并同意<text class="login-page__agreement-link" @tap.stop="openAgreement('user')"
          >《用户服务协议》</text
        >和<text class="login-page__agreement-link" @tap.stop="openAgreement('privacy')"
          >《隐私政策》</text
        >
      </text>
    </view>
  </view>
</template>

<script setup lang="ts">
import { onLoad } from "@dcloudio/uni-app";
import { ref } from "vue";
import { loginWithWechatPhone, AUTH_ERROR_MESSAGE } from "@/api/auth";
import { BusinessError } from "@/utils/request";
import { useLoginFlowStore } from "@/store/login-flow";
import { useUserStore } from "@/store/user";
import { enterAfterLogin } from "@/utils/profile-flow";

const agreedToTerms = ref(false);
const loginFlow = useLoginFlowStore();
const userStore = useUserStore();

onLoad(() => {
  // 已登录则跳过登录页，直接进入首页（见 design.md Uniapp 小节 Decisions 第 2 条）
  if (userStore.isLoggedIn) {
    uni.reLaunch({ url: "/pages/index/index" });
  }
});

function toggleAgreement() {
  agreedToTerms.value = !agreedToTerms.value;
  loginFlow.setAgreedToTerms(agreedToTerms.value);
}

function onWechatButtonTap() {
  if (!agreedToTerms.value) {
    uni.showToast({ title: "请先阅读并同意用户协议和隐私政策", icon: "none" });
  }
}

interface GetPhoneNumberEvent {
  detail: {
    errMsg: string;
    code?: string;
  };
}

async function onGetPhoneNumber(e: GetPhoneNumberEvent) {
  if (!agreedToTerms.value) {
    // 理论上 disabled 态不会触发本回调，这里只是双重保险（见 spec.md「登录前用户协议确认」）
    uni.showToast({ title: "请先阅读并同意用户协议和隐私政策", icon: "none" });
    return;
  }

  const { code, errMsg } = e.detail;

  if (!code) {
    // 用户在微信授权弹窗中点击拒绝/取消（见 spec.md「用户拒绝微信手机号授权」场景）
    if (!/ok$/i.test(errMsg ?? "")) {
      uni.showToast({ title: "已取消微信授权，可使用其他号码登录", icon: "none" });
    }
    return;
  }

  uni.showLoading({ title: "登录中...", mask: true });
  try {
    const result = await loginWithWechatPhone({ code, agreedToTerms: true });
    userStore.login(result);
    await enterAfterLogin();
  } catch (error) {
    const message =
      error instanceof BusinessError
        ? (AUTH_ERROR_MESSAGE[error.code] ?? error.message)
        : "登录失败，请稍后再试";
    uni.showToast({ title: message, icon: "none" });
  } finally {
    uni.hideLoading();
  }
}

function onOtherPhoneLogin() {
  if (!agreedToTerms.value) {
    uni.showToast({ title: "请先阅读并同意用户协议和隐私政策", icon: "none" });
    return;
  }
  uni.navigateTo({ url: "/pages/login/phone" });
}

function openAgreement(type: "user" | "privacy") {
  uni.navigateTo({ url: `/pages/agreement/index?type=${type}` });
}
</script>

